/// مفتاح التخزين للغة المختارة
const String kStorageLocale = 'app_locale';

/// يُحدَّث عند تغيير اللغة لإعادة بناء [GetMaterialApp] باللغة الجديدة.
final ValueNotifier<int> appLocaleRevision = ValueNotifier<int>(0);

/// هل اللغة الحالية من اليمين لليسار؟ (العربية أو الفارسية)
bool isAppRtl() {
  final code =
      Get.locale?.languageCode ??
      GetStorage().read(kStorageLocale) as String? ??
      'en';
  return code == 'ar' || code == 'fa';
}

/// اتجاه النص حسب لغة التطبيق (التطبيق يفرض LTR عالمياً؛ استخدم هذا محلياً).
TextDirection get appTextDirection =>
    isAppRtl() ? TextDirection.rtl : TextDirection.ltr;

/// يغلف واجهة باتجاه اللغة الحالية (عربي يمين، إنجليزي يسار).
Widget wrapAppDirectionality({required Widget child}) {
  return Directionality(textDirection: appTextDirection, child: child);
}

/// تحديث لغة التطبيق وحفظها
void setAppLocale(String languageCode) {
  Get.updateLocale(Locale(languageCode));
  GetStorage().write(kStorageLocale, languageCode);
  appLocaleRevision.value++;
}

/// إرجاع مفتاح الترجمة لحالة التفعيل (نشط، غير مفعل، ...)
String activationStatusKey(String status) {
  switch (status) {
    case 'نشط':
      return 'activation_active';
    case 'منتهي':
      return 'activation_expired';
    case 'محظور':
      return 'activation_blocked';
    case 'checking':
    case 'جاري التحقق...':
    case 'Checking...':
      return 'checking';
    default:
      return 'activation_inactive';
  }
}
